import pandas as pd, re, json, math
from collections import defaultdict

# Load codebooks
codebook_files = {
    'P1_POWER': '/app/data/codebook_P1_POWER.csv',
    'P2_CTRL': '/app/data/codebook_P2_CTRL.csv',
    'P3_RF': '/app/data/codebook_P3_RF.csv',
}

# Generic words to down-weight
GENERIC_WORDS = {
    'open','short','fail','failed','failure','error','err','issue','problem','ng','bad','abnormal','suspect','suspected',
    'high','low','over','under','unstable','intermittent','noise','unknown','fault','alarm',
    '异常','不良','失败','错误','问题','疑似','怀疑','不稳','间歇','偏高','偏低'
}

GENERIC_CN = {'异常','不良','失败','错误','问题','疑似','怀疑','不稳','间歇','偏高','偏低'}

COMPONENT_PATTERN = re.compile(r'\b(?:TP|ANT|SH|SW|J|U|R|C|L|Q|T)\d+[A-Z0-9_]*\b', re.I)


def calc_weight(kw: str) -> float:
    kw_l = kw.lower().strip()
    if not kw_l:
        return 0.0
    if kw_l in GENERIC_WORDS:
        return 0.4
    if re.search(r'[0-9_]', kw_l):
        return 2.0
    if re.search(r'[\u4e00-\u9fff]', kw_l):
        return 1.3 if len(kw_l) >= 2 else 0.6
    if len(kw_l) >= 5:
        return 1.1
    if len(kw_l) >= 3:
        return 0.9
    return 0.7


def is_specific_kw(kw: str) -> bool:
    kw_l = kw.lower().strip()
    if not kw_l:
        return False
    if re.search(r'[0-9_]', kw_l):
        return True
    if COMPONENT_PATTERN.match(kw):
        return True
    if re.search(r'[\u4e00-\u9fff]', kw_l):
        return kw_l not in GENERIC_CN
    if len(kw_l) >= 5 and kw_l not in GENERIC_WORDS:
        return True
    return False


def build_entries(path):
    df = pd.read_csv(path)
    entries = []
    for _, row in df.iterrows():
        keywords = []
        # keywords_examples
        for kw in str(row['keywords_examples']).split(','):
            kw = kw.strip()
            if kw and kw not in keywords:
                keywords.append(kw)
        # tokens from standard_label
        label = str(row['standard_label'])
        tokens = re.findall(r'[A-Za-z0-9_]+', label)
        tokens += re.findall(r'[\u4e00-\u9fff]{2,}', label)
        for t in tokens:
            if t and t not in keywords:
                keywords.append(t)
        kw_info = []
        total_weight = 0.0
        for kw in keywords:
            weight = calc_weight(kw)
            if weight <= 0:
                continue
            kw_info.append((kw, kw.lower(), weight, is_specific_kw(kw)))
            total_weight += weight
        station_scope = set([s.strip().upper() for s in str(row['station_scope']).split(';') if s.strip()])
        entries.append({
            'code': row['code'],
            'label': row['standard_label'],
            'station_scope': station_scope,
            'keywords': kw_info,
            'total_weight': total_weight if total_weight > 0 else 1.0,
        })
    return entries

codebooks = {pid: build_entries(path) for pid, path in codebook_files.items()}

# segmentation
SEP_PATTERN = re.compile(r'\s*(?:[;；]|\n)\s*|\s+[+/&\|]\s+')


def split_segments(text: str):
    if text is None:
        return []
    t = str(text).strip()
    if not t:
        return []
    # Protect alnum/alnum slashes like C87/VDD_5V
    def protect(m):
        return m.group(1) + '§' + m.group(2)
    t2 = re.sub(r'([A-Za-z0-9_]{2,})/([A-Za-z0-9_]{2,})', protect, t)
    parts = [p.strip() for p in SEP_PATTERN.split(t2) if p and p.strip()]
    # restore protected slashes
    parts = [p.replace('§', '/') for p in parts]
    return parts if parts else [t]


def best_match(segment: str, entries, station: str):
    seg = segment.lower()
    best = None
    best_score = 0.0
    best_specific = 0
    for entry in entries:
        matched_weight = 0.0
        matched_specific = 0
        for kw, kw_l, weight, is_spec in entry['keywords']:
            if kw_l and kw_l in seg:
                matched_weight += weight
                if is_spec:
                    matched_specific += 1
        if matched_weight <= 0:
            score = 0.0
        else:
            score = matched_weight / entry['total_weight']
            # station bonus
            if station and station in entry['station_scope']:
                score += 0.07
            # slight boost for multiple specific hits
            if matched_specific >= 2:
                score += 0.05
            score = min(score, 1.0)
        if score > best_score:
            best_score = score
            best = entry
            best_specific = matched_specific
    return best, best_score, best_specific


def calibrate_confidence(score: float, known: bool, matched_specific: int):
    if not known:
        conf = 0.05 + 0.3 * score
        return round(min(conf, 0.3), 3)
    conf = 0.4 + 0.6 * score
    if matched_specific >= 2:
        conf += 0.05
    return round(min(conf, 0.98), 3)


logs = pd.read_csv('/app/data/test_center_logs.csv')

records_out = []
for _, row in logs.iterrows():
    record_id = row['record_id']
    product_id = row['product_id']
    station = str(row['station']).upper()
    engineer_id = row['engineer_id']
    raw_reason_text = str(row['raw_reason_text'])

    segments = split_segments(raw_reason_text)
    normalized = []
    entries = codebooks.get(product_id, [])

    for i, seg in enumerate(segments, start=1):
        if not seg:
            continue
        pred_code = 'UNKNOWN'
        pred_label = ''
        best_score = 0.0
        matched_specific = 0
        if entries:
            best_entry, best_score, matched_specific = best_match(seg, entries, station)
            # threshold for unknown
            if best_entry and (best_score >= 0.28 or (best_score >= 0.4 and matched_specific > 0)):
                pred_code = best_entry['code']
                pred_label = best_entry['label']
            else:
                best_entry = None
        known = pred_code != 'UNKNOWN'
        confidence = calibrate_confidence(best_score, known, matched_specific)
        normalized.append({
            'segment_id': f"{record_id}-S{i}",
            'span_text': seg,
            'pred_code': pred_code,
            'pred_label': pred_label,
            'confidence': confidence,
            'rationale': f"Matched keywords score={best_score:.2f}; specific_hits={matched_specific}; station={station}" if known else f"Low match score={best_score:.2f}; specific_hits={matched_specific}; station={station}"
        })

    if not normalized:
        normalized.append({
            'segment_id': f"{record_id}-S1",
            'span_text': raw_reason_text,
            'pred_code': 'UNKNOWN',
            'pred_label': '',
            'confidence': 0.05,
            'rationale': f"Empty/unsplittable text; station={station}"
        })

    records_out.append({
        'record_id': record_id,
        'product_id': product_id,
        'station': station,
        'engineer_id': engineer_id,
        'raw_reason_text': raw_reason_text,
        'normalized': normalized,
    })

out_path = '/app/output/solution.json'
with open(out_path, 'w', encoding='utf-8') as f:
    json.dump({'records': records_out}, f, ensure_ascii=False, indent=2)

print('wrote', out_path, 'records', len(records_out))
print('sample normalized:')
for r in records_out[:3]:
    print(r['record_id'], r['normalized'])
